document.head.insertAdjacentHTML("beforeend", "<link rel=\"stylesheet\" href=\"https://testingcf.jsdelivr.net/npm/@fontsource/noto-serif-sc@5.3.1/400.css\">\n<link rel=\"stylesheet\" href=\"https://testingcf.jsdelivr.net/npm/@fontsource/noto-serif-sc@5.3.1/700.css\">\n<link rel=\"stylesheet\" href=\"https://testingcf.jsdelivr.net/npm/@fontsource/fraunces@5.3.0/900.css\">\n<link rel=\"stylesheet\" href=\"https://testingcf.jsdelivr.net/npm/@fontsource/dm-serif-display@5.3.0/400.css\">");
document.body.insertAdjacentHTML("afterbegin", "<div id=\"intro\">\n<div class=\"cover\"><img class=\"day\" src=\"https://testingcf.jsdelivr.net/gh/ssd-tavern/midsommar@1.1.1/assets/intro-cover-v2.webp\" alt=\"\"><img class=\"night\" src=\"https://testingcf.jsdelivr.net/gh/ssd-tavern/midsommar@1.1.1/assets/intro-cover-night.webp\" alt=\"\" loading=\"lazy\"><div class=\"tgl\" title=\"日间与夜间\"></div><div class=\"title\"><span>MIDSOMMAR</span>仲夏夜</div></div>\n<div class=\"seam\"></div>\n<div class=\"main\">\n<div class=\"lead\" data-b=\"0\"><p class=\"b0\">毕业季，你陪女友洛槿、还有她的同学祝凛，跟着瑞典闺蜜莉妮娅一起飞往瑞典中部的哈尔辛兰。</p><p class=\"b1\">毕业季，你和莉妮娅要回家了。你们都生在瑞典中部哈尔辛兰的山谷里，被村子送到中国读人类学，这一趟带上了莉妮娅的闺蜜洛槿和你的同学祝凛。</p><p>山谷深处的哈尔加村，今年夏至正赶上九十年一次的庆典。这里的极昼太阳不落，村里人都会换上亲手织的白色亚麻衣裙，围着五月柱跳舞。</p><p class=\"b0\">只是你还没意识到，这场旅行从一开始就不是单纯的做客——莉妮娅和村里的姑娘们，正盘算着把你永远留在哈尔加。是顺从她们的挽留，还是带着身边的人离开？接下来的每一步怎么走，全由你决定。</p><p class=\"b1\">她们只当这是一趟毕业旅行。只有你和莉妮娅知道，长老会在等你们把新血带回来——村子要她们留下，做你的新娘。是把她们一步步领进哈尔加，还是在第九天带她们逃离？接下来的每一步怎么走，全由你决定。</p></div>\n<div class=\"pv\"><video controls playsinline preload=\"none\" poster=\"https://testingcf.jsdelivr.net/gh/ssd-tavern/midsommar@1.1.1/assets/pv-poster.webp\"><source src=\"https://testingcf.jsdelivr.net/gh/ssd-tavern/midsommar@1.1.1/assets/pv.webm\" type='video/webm; codecs=\"av01.0.08M.10, opus\"'><source src=\"https://testingcf.jsdelivr.net/gh/ssd-tavern/midsommar@1.1.1/assets/pv.mp4\" type=\"video/mp4\"></video></div>\n<h2>玩法说明</h2>\n<div class=\"grid g2\">\n<div class=\"cell\" style=\"--c:var(--ms-yellowd)\"><span class=\"t\">体验剧情</span>在精心设计的十天日程下，哈尔加的庆典从清晨持续到不落的夜晚。每个时段都有新节目等你参与。</div>\n<div class=\"cell\" style=\"--c:var(--ms-red)\"><span class=\"t\">场景探索</span>经历机场、旅途与村外草地的序章后，即可在村内 17 处场景间自由移动，全场景均配备独立插画。</div>\n<div class=\"cell\" style=\"--c:var(--ms-pink)\"><span class=\"t\">发展关系</span>五位女主，五段心事。与她们并肩度过庆典的每个时段，你的一言一行都将改变她们看你的眼神。</div>\n<div class=\"cell\" style=\"--c:var(--ms-blue)\"><span class=\"t\">你的结局</span>九天庆典落幕之际，去留全凭你抉择。是留在哈尔加，还是踏上归途，你的选择将通向怎样的结局？</div>\n</div>\n<h2 class=\"pickh\">选择视角</h2>\n<div class=\"grid g2 picks\">\n<button class=\"pick on\" data-b=\"0\" data-n=\"1\" style=\"--c:var(--ms-red)\"><span class=\"t\">男友线</span>你是洛槿的男友，陪女友和她的同学，跟着瑞典闺蜜回村过节。</button>\n<button class=\"pick\" data-b=\"1\" data-n=\"2\" style=\"--c:var(--ms-yellowd)\"><span class=\"t\">村民线</span>你是哈尔加的村民，和莉妮娅一起在中国留学，把洛槿和祝凛带回村。</button>\n</div>\n<div class=\"go\"><button id=\"go\">即刻启程</button></div>\n<p class=\"credit\">制卡 ssd（类脑 @buyssdcom）<span>禁止二创二改二传</span></p>\n</div>\n</div>\n<style>\n:root{--ms-paper:#FBFAF6;--ms-paper2:#F2F1EA;--ms-card:#FFFFFF;--ms-ink:#27302A;--ms-muted:#6B7166;--ms-line:#E2DFD3;--ms-green:#5E7E44;--ms-brick:#A63A28;--ms-yellow:#E8B923;--ms-yellowd:#B88A0F;--ms-red:#D8452F;--ms-blue:#3F6FB5;--ms-blued:#27407A;--ms-pink:#E48AA3;--ms-violet:#8A6CB4;--ms-rule:#CFCBBB;--ms-themeicon:url(\"data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20width%3D%2716%27%20height%3D%2716%27%3E%3Cpath%20d%3D%27M13.5%2010.2A6%206%200%200%201%205.8%202.5A6%206%200%201%200%2013.5%2010.2Z%27%20fill%3D%27%23fff%27%2F%3E%3C%2Fsvg%3E\")}:root[data-ms-theme=\"dark\"]{--ms-paper:#1D221E;--ms-paper2:#262C27;--ms-card:#2B322C;--ms-ink:#E4E1D5;--ms-muted:#A3A898;--ms-line:#3A433B;--ms-green:#94B370;--ms-brick:#EC8A70;--ms-yellow:#E8B923;--ms-yellowd:#E3B33A;--ms-red:#E8664F;--ms-blue:#8AAAE0;--ms-blued:#7395D6;--ms-pink:#E99AB1;--ms-violet:#B095D8;--ms-rule:#4C554B;--ms-themeicon:url(\"data:image/svg+xml,%3Csvg%20xmlns%3D%27http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%27%20width%3D%2716%27%20height%3D%2716%27%3E%3Ccircle%20cx%3D%278%27%20cy%3D%278%27%20r%3D%273.2%27%20fill%3D%27%23fff%27%2F%3E%3Cpath%20d%3D%27M8%201v2M8%2013v2M1%208h2M13%208h2M3%203l1.4%201.4M11.6%2011.6L13%2013M3%2013l1.4-1.4M11.6%204.4L13%203%27%20stroke%3D%27%23fff%27%20stroke-width%3D%271.5%27%20stroke-linecap%3D%27round%27%2F%3E%3C%2Fsvg%3E\")}\n*{box-sizing:border-box;margin:0;padding:0}\nhtml,body{overflow:hidden}\nbody{font-family:\"Noto Serif SC\",\"Source Han Serif SC\",\"Songti SC\",\"STSong\",\"SimSun\",serif;font-size:14px;line-height:1.7;color:var(--ms-ink);background:transparent}\n#intro{background:var(--ms-paper);border:1px solid var(--ms-line);border-radius:12px;overflow:hidden}\n.cover{position:relative;aspect-ratio:3/2}\n.cover img{display:block;width:100%;height:100%;object-fit:cover}\n/* 日间、夜间各一张头图；右上角是和场景图同款的日夜开关 */\n.cover .night,:root[data-ms-theme=\"dark\"] .cover .day{display:none}\n:root[data-ms-theme=\"dark\"] .cover .night{display:block}\n.tgl{position:absolute;z-index:2;top:10px;right:10px;width:32px;height:32px;background:var(--ms-themeicon) center/18px no-repeat;filter:drop-shadow(0 1px 3px rgba(20,16,12,.7));opacity:.85;cursor:pointer;transition:opacity .15s}\n.tgl:hover{opacity:1}\n.cover::after{content:\"\";position:absolute;inset:55% 0 0;background:linear-gradient(transparent,rgba(20,24,18,.62))}\n.title{position:absolute;left:0;right:0;bottom:6%;z-index:1;text-align:center;font-size:40px;font-weight:700;letter-spacing:.32em;text-indent:.32em;line-height:1.2;color:#fff;text-shadow:0 2px 14px rgba(0,0,0,.45)}\n.title span{display:block;margin-bottom:4px;font-size:11px;font-weight:400;letter-spacing:.6em;text-indent:.6em;opacity:.85}\n.pv{margin-top:16px;aspect-ratio:16/9;background:#000;border-radius:8px;overflow:hidden}\n.pv video{display:block;width:100%;height:100%}\n.seam{height:4px;background:linear-gradient(90deg,var(--ms-green),var(--ms-yellow),var(--ms-red),var(--ms-pink),var(--ms-violet),var(--ms-blue))}\n.main{padding:16px 18px 18px}\n.lead{position:relative;margin:6px 0 0 14px;padding-left:22px;border-left:1px solid color-mix(in srgb,var(--ms-green) 45%,transparent);font-size:16px;line-height:2;text-align:justify}\n.lead::before{content:\"\\201C\";position:absolute;left:-19px;top:-10px;width:36px;height:32px;background:var(--ms-paper);text-align:center;font:900 46px/1 \"Fraunces\",serif;color:var(--ms-green)}\n.lead p+p{margin-top:6px}\n.lead[data-b=\"0\"] .b1,.lead[data-b=\"1\"] .b0{display:none}\n.lead .b0+p,.lead .b1+p{margin-top:6px}\nh2{margin:22px 0 10px;font-size:17px;letter-spacing:.14em}\n.grid{display:grid;gap:8px;counter-reset:n}\n.g2{grid-template-columns:repeat(2,1fr)}\n.cell{position:relative;counter-increment:n;padding:10px 12px 11px;border:1px solid var(--ms-line);border-radius:8px;background:var(--ms-card);font-size:15px;line-height:1.9}\n.cell::after{content:counter(n,decimal-leading-zero);position:absolute;right:14px;top:6px;font:400 32px/1 \"DM Serif Display\",serif;color:color-mix(in srgb,var(--c) 28%,transparent)}\n.cell .t{display:block;margin-bottom:3px;font-size:15px;font-weight:700;letter-spacing:.1em;color:var(--c)}\n/* 视角：选中的一张描边并铺一层淡色，左上一个圆点 */\n.pick{position:relative;padding:10px 12px 11px 34px;border:1px solid var(--ms-line);border-radius:8px;background:var(--ms-card);font:inherit;font-size:14px;line-height:1.85;text-align:left;color:var(--ms-ink);cursor:pointer;transition:background .15s,border-color .15s}\n.pick::before{content:\"\";position:absolute;left:12px;top:17px;width:12px;height:12px;border:1.6px solid var(--ms-muted);border-radius:50%}\n.pick .t{display:block;margin-bottom:2px;font-size:15px;font-weight:700;letter-spacing:.1em;color:var(--c)}\n.pick:hover{border-color:color-mix(in srgb,var(--c) 50%,var(--ms-line))}\n.pick.on{border-color:var(--c);background:color-mix(in srgb,var(--c) 10%,var(--ms-card))}\n.pick.on::before{border-color:var(--c);background:radial-gradient(var(--c) 0 3px,transparent 3.5px)}\n.go{display:flex;flex-direction:column;align-items:center;gap:8px;margin-top:18px}\n#go{padding:9px 44px;border:0;border-radius:8px;background:var(--ms-green);font:inherit;font-size:16px;letter-spacing:.3em;text-indent:.3em;color:var(--ms-paper);cursor:pointer;transition:filter .15s}\n#go:hover{filter:brightness(1.1)}\n.credit{margin-top:14px;font-size:11.5px;letter-spacing:.06em;text-align:center;color:var(--ms-muted)}\n.credit span{margin-left:1.5em}\n@media (max-width:520px){.main{padding:14px 12px 16px}.lead{font-size:15px;line-height:1.95}.title{font-size:30px}.cell,.cell .t{font-size:14px}.picks{grid-template-columns:1fr}}\n</style>");
const msRoot = window.parent.document.documentElement;
if (!msRoot.dataset.msTheme) {
  let t = 'light';
  try { t = window.parent.localStorage.getItem('ms-theme') || t; } catch {}
  msRoot.dataset.msTheme = t;
}
const msSync = () => { document.documentElement.dataset.msTheme = msRoot.dataset.msTheme; };
msSync();
new MutationObserver(msSync).observe(msRoot, { attributes: true, attributeFilter: ['data-ms-theme'] });
document.querySelector('.tgl').addEventListener('click', () => {
  msRoot.dataset.msTheme = msRoot.dataset.msTheme === 'dark' ? 'light' : 'dark';
  try { window.parent.localStorage.setItem('ms-theme', msRoot.dataset.msTheme); } catch {}
});
// 老版本的卡只有一篇开场白，也读这份前端：没有对应开场白的视角不显示，只剩一条时整块不显示
let total = 0;
try { total = getChatMessages(0, { include_swipes: true })[0]?.swipes?.length ?? 0; } catch {}
document.querySelectorAll('.pick').forEach((b) => { if (Number(b.dataset.n) >= total) b.remove(); });
const picks = [...document.querySelectorAll('.pick')];
if (picks.length < 2) document.querySelectorAll('.pickh,.picks').forEach((x) => (x.style.display = 'none'));
// 选视角：导语跟着换，即刻启程跳到对应的开场白
let cur = picks[0];
picks.forEach((b) => b.addEventListener('click', () => {
  cur = b;
  picks.forEach((x) => x.classList.toggle('on', x === b));
  document.querySelector('.lead').dataset.b = b.dataset.b;
}));
// 不用 /swipe（老版本酒馆没有）：先不刷新地把开场楼设到目标的前一页，再替玩家点一下开场楼的右箭头，由酒馆走完整的切页，渲染、事件与 MVU 初值都照常
document.getElementById('go').addEventListener('click', async () => {
  const n = Number(cur?.dataset.n ?? 1);
  await setChatMessages([{ message_id: 0, swipe_id: n - 1 }], { refresh: 'none' });
  window.parent.document.querySelector('#chat .mes[mesid="0"] .swipe_right')?.click();
});
